-- jangan menyentuh orang-orang–yang–Ku–urapi dan–kepada–nabi-nabi–Ku jangan berbuat–jahat
BEGIN;
-- 1910501501: אַֽל־ (H0408) → "jangan" [opus-4.5-chirho]
WITH np AS (
  INSERT INTO phrase (language_id, created_at)
  SELECT (SELECT id FROM language WHERE code = 'ind'), NOW()
  WHERE NOT EXISTS (
    SELECT 1 FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
    WHERE pw.word_id = '1910501501' AND p.language_id = (SELECT id FROM language WHERE code = 'ind') AND p.deleted_at IS NULL
  )
  RETURNING id
)
INSERT INTO phrase_word (phrase_id, word_id) SELECT id, '1910501501' FROM np ON CONFLICT DO NOTHING;
